ROUTE = (
    'load_order', 'lookup_supplier', 'get_reference_price',
    'calculate_variance', 'search_contract_terms',
)

def workflow_next(completed):
    if type(completed) is not set or any(type(value) is not str for value in completed):
        raise TypeError('completed_invalid')
    if not completed <= set(ROUTE):
        raise ValueError('unknown_action')
    prefix_length = 0
    while prefix_length < len(ROUTE) and ROUTE[prefix_length] in completed:
        prefix_length += 1
    if completed != set(ROUTE[:prefix_length]):
        raise ValueError('unreachable_state')
    return ROUTE[prefix_length] if prefix_length < len(ROUTE) else 'finish'

TOOL_ACTIONS = frozenset({
    'load_order', 'lookup_supplier', 'get_reference_price',
    'calculate_variance', 'search_contract_terms',
})

def proposal_decision(raw_action, completed, ready):
    if type(completed) is not frozenset or any(
        type(value) is not str or value not in TOOL_ACTIONS for value in completed
    ):
        raise TypeError('completed_invalid')
    if type(ready) is not bool:
        raise TypeError('ready_invalid')
    if type(raw_action) is not str or raw_action not in TOOL_ACTIONS | {'finish'}:
        return 'unsupported'
    if raw_action == 'finish':
        return 'finish' if ready else 'incomplete'
    if raw_action in completed:
        return 'duplicate'
    return 'execute'

STATE_KEYS = frozenset({'order', 'supplier', 'reference', 'variance', 'contract'})

def prerequisite_ok(action, state):
    if type(state) is not dict or set(state) != STATE_KEYS or any(
        type(value) is not bool for value in state.values()
    ):
        raise TypeError('state_invalid')
    requirements = {
        'load_order': (),
        'lookup_supplier': ('order',),
        'get_reference_price': ('order',),
        'calculate_variance': ('order', 'reference'),
        'search_contract_terms': ('order',),
        'finish': ('order', 'supplier', 'reference', 'variance', 'contract'),
    }
    if type(action) is not str or action not in requirements:
        raise ValueError('unknown_action')
    return all(state[key] for key in requirements[action])

