import copy

ACTION_SLOT = {
    'load_order': ('order', 'order'),
    'lookup_supplier': ('supplier', 'supplier'),
    'get_reference_price': ('reference', 'reference'),
    'calculate_variance': ('variance', 'variance'),
    'search_contract_terms': ('contract', 'contract'),
}
STATE_KEYS = frozenset({'order', 'supplier', 'reference', 'variance', 'contract', 'completed'})

def apply_observation(state, action, fact):
    if type(state) is not dict or set(state) != STATE_KEYS or type(state['completed']) is not frozenset:
        raise TypeError('state_invalid')
    if type(fact) is not dict or set(fact) != {'kind', 'value'} or type(fact['kind']) is not str:
        raise TypeError('fact_invalid')
    if type(action) is not str or action not in ACTION_SLOT:
        raise ValueError('unknown_action')
    slot, expected_kind = ACTION_SLOT[action]
    if fact['kind'] != expected_kind:
        raise ValueError('tool_result_mismatch')
    result = copy.deepcopy(state)
    result[slot] = copy.deepcopy(fact['value'])
    result['completed'] = frozenset((*state['completed'], action))
    return result

REQUIRED_FACTS = ('order', 'supplier', 'reference', 'variance', 'contract')

def ready_for_report(state):
    if type(state) is not dict:
        raise TypeError('state_invalid')
    return all(key in state and state[key] is not None for key in REQUIRED_FACTS)

import re
from decimal import Decimal

DECIMAL = re.compile(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?')

def _number(value):
    if type(value) is not str:
        raise TypeError('decimal_type')
    if DECIMAL.fullmatch(value) is None:
        raise ValueError('decimal_invalid')
    return Decimal(value)

def recommendation(supplier_status, variance_percent, terms_found, max_variance_percent):
    if type(supplier_status) is not str:
        raise TypeError('supplier_status_type')
    if not supplier_status or supplier_status != supplier_status.strip() or len(supplier_status) > 40:
        raise ValueError('supplier_status_invalid')
    if type(terms_found) is not bool:
        raise TypeError('terms_found_type')
    variance = _number(variance_percent)
    if not terms_found:
        if max_variance_percent is not None:
            raise ValueError('unexpected_threshold')
        return 'needs_human'
    threshold = _number(max_variance_percent)
    if threshold < 0:
        raise ValueError('threshold_invalid')
    if supplier_status != 'active' or variance > threshold:
        return 'review_required'
    return 'no_review'

