import re
from decimal import Decimal, ROUND_HALF_EVEN, localcontext

AMOUNT = re.compile(r'(?:0|[1-9][0-9]*)(?:\.[0-9]+)?')

def _amount(value):
    if type(value) is not str:
        raise TypeError('amount_type')
    if AMOUNT.fullmatch(value) is None:
        raise ValueError('amount_invalid')
    return Decimal(value)

def price_variance(reference, current, reference_currency, current_currency, reference_unit, current_unit):
    labels = (reference_currency, current_currency, reference_unit, current_unit)
    if any(type(value) is not str for value in labels):
        raise TypeError('label_type')
    if any(not value or value != value.strip() for value in labels):
        raise ValueError('label_invalid')
    if reference_currency != current_currency or reference_unit != current_unit:
        raise ValueError('prices_not_comparable')
    baseline = _amount(reference)
    observed = _amount(current)
    if baseline <= 0:
        raise ValueError('reference_price_invalid')
    with localcontext() as context:
        context.prec = 28
        absolute = observed - baseline
        percent = (absolute / baseline) * Decimal('100')
        quantum = Decimal('0.01')
        absolute = absolute.quantize(quantum, rounding=ROUND_HALF_EVEN)
        percent = percent.quantize(quantum, rounding=ROUND_HALF_EVEN)
    if absolute == 0:
        absolute = abs(absolute)
    if percent == 0:
        percent = abs(percent)
    return format(absolute, '.2f'), format(percent, '.2f')

