ROUTE = (
    'load_order', 'lookup_supplier', 'get_reference_price',
    'calculate_variance', 'search_contract_terms',
)
TOOLS = frozenset(ROUTE)

def bounded_agent(choices, max_steps=8):
    if type(choices) is not tuple or any(type(value) is not str for value in choices):
        raise TypeError('choices_invalid')
    if type(max_steps) is not int:
        raise TypeError('max_steps_type')
    if not 1 <= max_steps <= 20:
        raise ValueError('max_steps_out_of_range')
    completed = set()
    model_calls = 0
    tool_calls = 0
    last_error = None
    for position in range(max_steps):
        raw = choices[position] if position < len(choices) else 'finish'
        model_calls += 1
        if raw not in TOOLS | {'finish'}:
            last_error = 'unsupported_action'
            continue
        if raw == 'finish':
            if completed == set(ROUTE):
                return {
                    'status':'awaiting_approval', 'model_calls':model_calls,
                    'tool_calls':tool_calls, 'completed':tuple(ROUTE),
                    'failure_reason':None,
                }
            last_error = 'incomplete_evidence'
            continue
        if raw in completed:
            last_error = 'duplicate_action'
            continue
        tool_calls += 1
        if raw != 'load_order' and 'load_order' not in completed:
            last_error = 'order_required'
            continue
        if raw == 'calculate_variance' and 'get_reference_price' not in completed:
            last_error = 'order_and_reference_required'
            continue
        completed.add(raw)
        last_error = None
    return {
        'status':'failed', 'model_calls':model_calls, 'tool_calls':tool_calls,
        'completed':tuple(action for action in ROUTE if action in completed),
        'failure_reason':last_error or 'step_budget_exhausted',
    }

