import re
from decimal import Decimal, ROUND_HALF_EVEN

PRICE = re.compile(r'(?:0|[1-9][0-9]*)(?:\.[0-9]+)?')

def _price(value):
    if type(value) is not str:
        raise TypeError('price_type')
    if PRICE.fullmatch(value) is None:
        raise ValueError('price_invalid')
    return Decimal(value)

def planner_usage(observed_counts, had_errors, input_price_per_million='1.00', output_price_per_million='3.00'):
    if type(observed_counts) is not tuple or type(had_errors) is not tuple:
        raise TypeError('series_type')
    if not observed_counts or len(observed_counts) != len(had_errors):
        raise ValueError('series_length')
    if any(type(value) is not int or value < 0 for value in observed_counts):
        raise TypeError('observed_count_invalid')
    if any(type(value) is not bool for value in had_errors):
        raise TypeError('error_flag_invalid')
    input_price = _price(input_price_per_million)
    output_price = _price(output_price_per_million)
    input_tokens = sum(120 + 35 * observed + (20 if error else 0) for observed, error in zip(observed_counts, had_errors))
    output_tokens = 12 * len(observed_counts)
    latency = sum(70 + 8 * observed for observed in observed_counts)
    cost = (
        (Decimal(input_tokens) * input_price + Decimal(output_tokens) * output_price)
        / Decimal('1000000')
    ).quantize(Decimal('0.000001'), rounding=ROUND_HALF_EVEN)
    return {
        'calls':len(observed_counts), 'input_tokens':input_tokens,
        'output_tokens':output_tokens, 'modeled_latency_ms':latency,
        'estimated_cost_usd':format(cost, '.6f'),
    }

