from hashlib import sha256
import json

REPORT_KEYS = frozenset({'case_id','purchase_order_id','recommendation','summary','evidence'})
RECOMMENDATIONS = frozenset({'no_review','review_required','needs_human'})

def report_digest(report):
    if type(report) is not dict:
        raise TypeError('report_type')
    if set(report) != REPORT_KEYS:
        raise ValueError('report_keys')
    for key in ('case_id','purchase_order_id','recommendation','summary'):
        if type(report[key]) is not str:
            raise TypeError('report_scalar_type')
        if not report[key]:
            raise ValueError('report_scalar_empty')
    if report['recommendation'] not in RECOMMENDATIONS:
        raise ValueError('recommendation_invalid')
    if type(report['evidence']) is not tuple or not report['evidence'] or any(
        type(value) is not str or not value for value in report['evidence']
    ):
        raise TypeError('evidence_invalid')
    payload = json.dumps(
        report, ensure_ascii=True, sort_keys=True, separators=(',', ':')
    )
    return sha256(payload.encode('utf-8')).hexdigest()

