import re
from decimal import Decimal, ROUND_HALF_EVEN

COST = re.compile(r'(?:0|[1-9][0-9]*)(?:\.[0-9]+)?')
KEYS = frozenset({'status','model_calls','tool_calls','estimated_model_cost_usd','modeled_latency_ms'})

def aggregate_runs(results):
    if type(results) is not list:
        raise TypeError('results_type')
    if not results:
        raise ValueError('results_empty')
    costs = []
    for row in results:
        if type(row) is not dict or set(row) != KEYS:
            raise ValueError('result_shape')
        if type(row['status']) is not str or row['status'] not in {'awaiting_approval','failed'}:
            raise ValueError('status_invalid')
        for key in ('model_calls','tool_calls','modeled_latency_ms'):
            if type(row[key]) is not int or row[key] < 0:
                raise TypeError('metric_invalid')
        value = row['estimated_model_cost_usd']
        if type(value) is not str:
            raise TypeError('cost_type')
        if COST.fullmatch(value) is None:
            raise ValueError('cost_invalid')
        costs.append(Decimal(value))
    runs = len(results)
    failures = sum(row['status'] == 'failed' for row in results)
    total_cost = sum(costs, start=Decimal('0')).quantize(Decimal('0.000001'), rounding=ROUND_HALF_EVEN)
    return {
        'runs':runs,
        'successful_investigations':runs-failures,
        'failures':failures,
        'failure_rate':f'{(failures/runs)*100:.1f}%',
        'average_model_calls':round(sum(row['model_calls'] for row in results)/runs, 2),
        'average_tool_calls':round(sum(row['tool_calls'] for row in results)/runs, 2),
        'total_estimated_model_cost_usd':format(total_cost, '.6f'),
        'average_modeled_latency_ms':round(sum(row['modeled_latency_ms'] for row in results)/runs, 2),
    }

def choose_controller(stable_sequence, deterministic_rules, route_uncertainty, evaluation_ready):
    values = (stable_sequence, deterministic_rules, route_uncertainty, evaluation_ready)
    if any(type(value) is not bool for value in values):
        raise TypeError('flag_invalid')
    if stable_sequence and deterministic_rules and not route_uncertainty:
        return 'workflow'
    if route_uncertainty and evaluation_ready:
        return 'hybrid' if deterministic_rules else 'agent_candidate'
    return 'workflow'

FIELDS = ('case_id','purchase_order_id','recommendation','summary','evidence')
RECOMMENDATIONS = frozenset({'no_review','review_required','needs_human'})

def report_gate(report, max_summary_chars):
    if type(report) is not dict:
        raise TypeError('report_type')
    if type(max_summary_chars) is not int:
        raise TypeError('summary_limit_type')
    if not 1 <= max_summary_chars <= 1000:
        raise ValueError('summary_limit_range')
    errors = []
    for field in FIELDS:
        if field not in report:
            errors.append(f'missing:{field}')
    for field in sorted(set(report) - set(FIELDS)):
        errors.append(f'unexpected:{field}')
    for field in ('case_id','purchase_order_id'):
        if field in report and (
            type(report[field]) is not str or not report[field].strip()
        ):
            errors.append(f'invalid:{field}')
    if 'recommendation' in report and (
        type(report['recommendation']) is not str
        or report['recommendation'] not in RECOMMENDATIONS
    ):
        errors.append('invalid:recommendation')
    if 'summary' in report and (
        type(report['summary']) is not str
        or not report['summary'].strip()
        or len(report['summary']) > max_summary_chars
    ):
        errors.append('invalid:summary')
    if 'evidence' in report:
        evidence = report['evidence']
        if (
            type(evidence) is not tuple or not evidence
            or any(type(value) is not str or not value.strip() for value in evidence)
            or len(set(evidence)) != len(evidence)
        ):
            errors.append('invalid:evidence')
    return {'ok':not errors, 'errors':tuple(errors)}

def worker_plan(requested, allowed, max_workers):
    if type(requested) is not tuple or type(allowed) is not frozenset:
        raise TypeError('worker_collection_type')
    if any(type(value) is not str or not value for value in (*requested, *allowed)):
        raise TypeError('worker_name_invalid')
    if type(max_workers) is not int:
        raise TypeError('max_workers_type')
    if not 1 <= max_workers <= 8:
        raise ValueError('max_workers_range')
    scheduled = []
    rejected = []
    seen = set()
    for name in requested:
        if name in seen:
            rejected.append(f'duplicate:{name}')
            continue
        seen.add(name)
        if name not in allowed:
            rejected.append(f'unsupported:{name}')
        elif len(scheduled) >= max_workers:
            rejected.append(f'capacity:{name}')
        else:
            scheduled.append(name)
    return {'scheduled':tuple(scheduled), 'rejected':tuple(rejected)}

