def merge_results(expected, results):
    if type(expected) is not tuple or not expected or any(
        type(value) is not str or not value for value in expected
    ):
        raise TypeError('expected_invalid')
    if len(set(expected)) != len(expected):
        raise ValueError('expected_duplicate')
    if type(results) is not list:
        raise TypeError('results_type')
    indexed = {}
    for row in results:
        if type(row) is not dict or set(row) != {'worker','value','source'}:
            raise TypeError('result_shape')
        if any(type(row[key]) is not str or not row[key] for key in ('worker','value','source')):
            raise TypeError('result_value')
        worker = row['worker']
        if worker not in expected:
            raise ValueError('worker_unknown')
        if worker in indexed:
            raise ValueError('worker_duplicate')
        indexed[worker] = (row['value'], row['source'])
    if set(indexed) != set(expected):
        raise ValueError('worker_missing')
    values = tuple(indexed[worker][0] for worker in expected)
    sources = tuple(f'{worker}:{indexed[worker][1]}' for worker in expected)
    return {'values':values, 'sources':sources, 'conflict':len(set(values)) > 1}

