def append_trace(trace, event, max_events, max_bytes):
    if type(trace) is not tuple or any(type(value) is not str or not value for value in trace):
        raise TypeError('trace_invalid')
    if type(event) is not str or not event:
        raise TypeError('event_invalid')
    if type(max_events) is not int or type(max_bytes) is not int:
        raise TypeError('limit_type')
    if max_events <= 0 or max_bytes <= 0:
        raise ValueError('limit_range')
    candidate = (*trace, event)
    if len(candidate) > max_events:
        raise ValueError('trace_event_budget')
    if len('\n'.join(candidate).encode('utf-8')) > max_bytes:
        raise ValueError('trace_byte_budget')
    return candidate

REASONS = frozenset({
    'awaiting_approval', 'duplicate_action', 'unsupported_action',
    'incomplete_evidence', 'step_budget_exhausted',
})

def summarize_trials(trials):
    if type(trials) is not list:
        raise TypeError('trials_type')
    if not trials:
        raise ValueError('trials_empty')
    seen = set()
    failures = {}
    successes = 0
    for row in trials:
        if type(row) is not dict or set(row) != {'task_id','success','terminal_reason'}:
            raise TypeError('trial_shape')
        task_id = row['task_id']
        success = row['success']
        reason = row['terminal_reason']
        if type(task_id) is not str or not task_id:
            raise TypeError('task_id_invalid')
        if task_id in seen:
            raise ValueError('task_id_duplicate')
        seen.add(task_id)
        if type(success) is not bool:
            raise TypeError('success_invalid')
        if type(reason) is not str or reason not in REASONS:
            raise ValueError('terminal_reason_invalid')
        if success != (reason == 'awaiting_approval'):
            raise ValueError('outcome_inconsistent')
        if success:
            successes += 1
        else:
            failures[reason] = failures.get(reason, 0) + 1
    total = len(trials)
    failed = total - successes
    return {
        'total':total, 'successes':successes, 'failures':failed,
        'failure_rate':f'{(failed/total)*100:.1f}%',
        'failure_reasons':tuple(sorted(failures.items())),
    }

